<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Student,Department,Teacher};use Illuminate\Http\Request;use Illuminate\Support\{Str,Facades\Storage};
class StudentController extends Controller{public function index(){return view('admin.students.index',['items'=>Student::with(['department','teacher'])->orderBy('sort')->orderBy('name')->paginate(50)]);}public function create(){return $this->form(new Student);}public function store(Request $r){Student::create($this->data($r));return redirect()->route('admin.students.index')->with('ok','Ученик добавлен');}public function edit(Student $student){return $this->form($student);}public function update(Request $r,Student $student){$old=$student->photo;$d=$this->data($r,$student);$student->update($d);if(isset($d['photo'])&&$old&&$old!==$d['photo'])Storage::disk('public')->delete($old);return redirect()->route('admin.students.index')->with('ok','Карточка ученика обновлена');}public function destroy(Student $student){if($student->photo)Storage::disk('public')->delete($student->photo);$student->delete();return back()->with('ok','Ученик удалён');}private function form(Student $item){return view('admin.students.form',['item'=>$item,'departments'=>Department::where('is_active',true)->orderBy('sort')->get(),'teachers'=>Teacher::where('is_active',true)->orderBy('name')->get()]);}private function data(Request $r,?Student $item=null){$d=$r->validate(['name'=>'required|max:255','department_id'=>'nullable|exists:departments,id','teacher_id'=>'nullable|exists:teachers,id','class_name'=>'nullable|max:100','instrument'=>'nullable|max:255','bio'=>'nullable','photo'=>'nullable|image|max:10240','sort'=>'nullable|integer|min:0']);$base=Str::slug($r->input('slug')?:$d['name'])?:'student';$slug=$base;$i=2;while(Student::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('photo'))$d['photo']=$r->file('photo')->store('students','public');$d['sort']=$d['sort']??0;$d['is_active']=$r->boolean('is_active');$d['is_public']=$r->boolean('is_public');return $d;}}